abstract evaluate(movement: NormalizedMovement, context: RuleContext): Promise<RuleResult>;
protected createMatch(
    customerId: string,
    confidence: number,
    evidence: EvidenceItem[],
  ): RuleResult {
    return {
      matched: true,
      customerId,
      confidence,
      evidence,
    };
